$\widehat{Q}\in \mathcal{L}((S),\mathcal{O}_{\infty})$ satisfies for $j,k \in \mathbb{N}$

\begin{eqnarray}
\widehat{Q}(1) &= Id, \\
{}[\widehat{Q}(f),\widehat{Q}(g)] &= -2i \widehat{Q}(\{f,g\}), \\
{}[\widehat{Q}(q_k),\widehat{Q}(q_j)] &= [\widehat{Q}(p_k),\widehat{Q}(p_j)]=0, [\widehat{Q}(q_k),
\widehat{Q}(p_j)] =  -2i \delta_{kj}Id, k,j\in\mathbb{N}.
\end{eqnarray}

Furthermore, if $\phi:\mathbb{R}\to\mathbb{R}$ is an analytic function then

\begin{equation}
\Re \widehat{Q}(\phi(f))=\phi(\Re\widehat{Q}(f))\\
\end{equation}
